function field(f,r){let val=r[f.name]??'';if(f.name==='assignmentDone')val=r.assignmentDone?'Yes':'No';const attrs=`id="f-${f.name}" name="${f.name}" ${f.required?'required':''}`;let input;if(f.type.startsWith('ref:')||f.type.startsWith('multi:')){const key=f.type.split(':')[1],multi=f.type.startsWith('multi:');input=`<select ${attrs} ${multi?'multiple':''}>${multi?'':'<option value="">Select '+esc(f.label.toLowerCase())+'</option>'}${db[key].map(o=>`<option value="${o.id}" ${(multi?(val||[]).includes(o.id):val===o.id)?'selected':''}>${esc(o.name)}</option>`).join('')}</select>${multi?'<small>Tap to select one or more.</small>':''}`;}else if(f.type==='select')input=`<select ${attrs}>${f.options.map(o=>`<option ${val===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`;else if(f.type==='textarea')input=`<textarea ${attrs} maxlength="4000">${esc(val)}</textarea>`;else input=`<input ${attrs} type="${f.type}" ${f.type==='number'?`min="${f.name==='age'||f.name==='sessions'?1:0}" step="${['age','sessions','batchSize','audience'].includes(f.name)?1:'.01'}" ${f.name==='commission'?'max="100"':''}`:'maxlength="300"'} value="${esc(val)}">`;return `<div class="field ${['textarea'].includes(f.type)||f.type.startsWith('multi:')?'wide':''}"><label for="f-${f.name}">${esc(f.label)}${f.required?' *':''}</label>${input}</div>`;}
function edit(k,id,overrides={}){if(!canEdit(k))return toast('This account cannot edit these records.');if(k==='registrations'&&id)return toast('Recorded registration payments cannot be altered.');if(k==='students'&&(!db.trainers.length||!db.courses.length))return modal('Set up your institute first','<p>Add at least one trainer and one work packet before enrolling students.</p><div class="actions">'+button('Add trainer','edit','data-key="trainers"')+button('Add work packet','edit','data-key="courses"','secondary')+'</div>');if(['sessions','fees','registrations'].includes(k)&&!db.students.length)return toast('Enrol a student first.');const r=normaliseDuration(k,{status:k==='sessions'?'Planned':k==='events'?'Planned':k==='registrations'?'Paid':'Active',enrollmentDate:M.today(),plannedDate:M.today(),dueDate:M.today(),date:M.today(),receipt:k==='registrations'?'REG-'+Date.now().toString().slice(-9):undefined,commission:0,discount:0,collections:0,organizerCharge:0,organizerReceived:0,...(id?find(k,id):{}),...overrides});let fields=schemas[k];if(user.role==='Artist')fields=fields.filter(f=>['availability','stagePreference','payoutExpectation','socialLinks'].includes(f.name));modal((id?'Edit ':'Add ')+singular[k],`<form data-form="record" data-key="${k}" data-id="${id||''}" novalidate><div class="fields">${fields.map(f=>field(f,r)).join('')}</div>${k==='fees'?'<div class="note">Record each collection separately after saving the fee plan. Discounts reduce the amount owed.</div>':''}${k==='registrations'?'<div class="note">Saving records the registration payment and receipt. Recorded payments cannot be altered or deleted.</div>':''}${k==='events'?'<div class="note">Add itemised expenses and artist payouts after saving. Earnings use billed organizer charges; cash surplus uses payments received.</div>':''}${k==='trainers'?'<div class="note">Commission is estimated on collections from assigned students. Mixed or per-session arrangements can be recorded in preferences.</div>':''}<div class="form-error" role="alert" aria-live="assertive"></div><div class="actions"><button type="submit" class="button">Save ${singular[k]}</button>${button('Cancel','close','','ghost')}</div></form>`);if(['sessions','fees'].includes(k))$('#f-studentId').addEventListener('change',()=>{const s=find('students',$('#f-studentId').value);if(!s)return;if($('#f-trainerId'))$('#f-trainerId').value=s.trainerId;$('#f-courseId').value=s.courseIds[0]||'';if(k==='fees'){const c=find('courses',s.courseIds[0]);$('#f-amount').value=c?.fee||0;}});}
function persist(action){try{if(preview){db.audit.unshift({id:M.id(),at:new Date().toISOString(),user:user.username,action});db.audit=db.audit.slice(0,500);localStorage.setItem('swara-preview',JSON.stringify(db));}else{const result=JSON.parse(A.saveState(JSON.stringify(db),action));if(result.error)throw Error(result.error);db=result.state;}render();return true;}catch(e){toast('Could not save: '+e.message);if(!preview){const r=JSON.parse(A.readState());if(r.state){db=r.state;render();}else if(r.error){close();showLogin();}}return false;}}
function view(k,id){const r=find(k,id);if(!r)return;let body=`<div class="detail"><h3>${esc(r.name|| (k==='sessions'?M.sessionName(db,r):nm('students',r.studentId)))}</h3><dl>${schemas[k].filter(f=>r[f.name]!==undefined&&r[f.name]!==''&&(!Array.isArray(r[f.name])||r[f.name].length)).map(f=>{let v=r[f.name];if(f.type.startsWith('ref:'))v=nm(f.type.split(':')[1],v);if(f.type.startsWith('multi:'))v=v.map(x=>nm(f.type.split(':')[1],x)).join(', ');if(f.name==='assignmentDone')v=v?'Yes':'No';return `<div><dt>${esc(f.label)}</dt><dd>${esc(v)}</dd></div>`;}).join('')}</dl></div>`;if(k==='students'){const p=M.progress(db,id);body+=`<h3>Learning progress</h3>${meta('Completed / target',`${p.completed} / ${p.planned}`,'Remaining',p.pending)}<div class="progress"><span style="width:${p.percent}%"></span></div>`;const sessions=db.sessions.filter(s=>s.studentId===id).sort((a,b)=>b.plannedDate.localeCompare(a.plannedDate));body+=`<h3 style="margin-top:20px">Session timeline</h3>${sessions.map(s=>`<div class="list-row"><div><b>${esc(s.plannedDate)} · ${esc(nm('courses',s.courseId))}</b><small>${esc(s.notes||s.assignment||'No notes yet')}</small></div>${badge(s.status)}</div>`).join('')||'<p class="muted">No sessions yet.</p>'}`;if(canEdit('sessions'))body+=`<div class="actions">${button('Schedule class','edit',`data-key="sessions" data-student="${id}"`,'small')}${button('Create fee plan','edit',`data-key="fees" data-student="${id}"`,'secondary small')}</div>`;}
if(k==='trainers'){const report=M.reports(db,'trainers');const row=report.rows[db.trainers.findIndex(t=>t.id===id)];body+=`<h3>Workload</h3>${meta('Assigned students',row?.[1]||0,'Completed sessions',row?.[2]||0)}${r.commission!==undefined?meta('Pending scheduled sessions',row?.[3]||0,'Estimated commission',row?.[5]||fmt(0)):''}<p class="muted" style="margin-top:12px">Commission estimate uses all collections from students currently assigned to this trainer. Review historical reassignment before payout.</p>`;}
if(k==='fees'){body+=`<div class="metrics">${metric('Net fee',fmt(M.charged(r)))}${metric('Balance',fmt(M.due(r)),'','warn')}</div><h3 style="margin-top:20px">Payment receipts</h3>${(r.payments||[]).map(p=>`<div class="list-row"><div><b>${esc(fmt(p.amount))} · ${esc(p.mode)}</b><small>${esc(p.date)} · ${esc(p.receipt)} ${esc(p.remarks||'')}</small></div>${button('Receipt','receipt',`data-id="${id}" data-payment="${p.id}"`,'ghost small')}</div>`).join('')||'<p class="muted">No payments recorded.</p>'}${canEdit(k)&&M.due(r)>0?button('Collect payment','paid',`data-id="${id}"`):''}<div class="actions">${button('Prepare fee reminder','fee-remind',`data-id="${id}"`,'secondary')}</div>`;}
if(k==='events'&&user.role==='Artist'&&r.ownPayouts){body+=`<h3>Your recorded payouts</h3>${r.ownPayouts.map(p=>`<div class="list-row"><div><b>${esc(p.description)}</b><small>${esc(p.date)}</small></div><b>${esc(fmt(p.amount))}</b></div>`).join('')||'<p class="muted">No payout recorded yet.</p>'}`;}if(k==='events'&&finance()){body+=`<div class="metrics">${metric('Total costs',fmt(M.eventCost(r)))}${metric('Net earnings',fmt(M.profit(r)),'Billed revenue less costs','tint')}${metric('Cash surplus',fmt(M.cashProfit(r)),'Received revenue less costs')}${metric('Organizer balance',fmt(Number(r.organizerCharge||0)-Number(r.organizerReceived||0)),'','warn')}</div><h3 style="margin-top:20px">Expense and payout ledger</h3>${(r.expenses||[]).map(e=>`<div class="list-row"><div><b>${esc(e.category)} ${e.artistId?'· '+esc(nm('artists',e.artistId)):''}</b><small>${esc(e.date)} · ${esc(e.description)} · ${esc(e.reference||'')}</small></div><b>${esc(fmt(e.amount))}</b></div>`).join('')||'<p class="muted">No expenses recorded.</p>'}${canEdit(k)?`<div class="actions">${button('Record expense / payout','expense',`data-id="${id}"`)}</div>`:''}`;}
if(k==='registrations')body+=`<div class="note">This registration payment is recorded as received and cannot be altered or deleted.</div><div class="actions">${button('Print registration receipt','registration-receipt',`data-id="${id}"`)}</div>`;body+=`<div class="actions" style="margin-top:24px">${canEdit(k)&&k!=='registrations'?button('Edit details','edit',`data-key="${k}" data-id="${id}"`,'secondary'):''}${canDelete(k)?button('Delete record','delete',`data-key="${k}" data-id="${id}"`,'danger'):''}</div>`;modal(labels[k]+' details',body);}
function paid(id){const f=find('fees',id);modal('Record fee collection',`<p>${esc(nm('students',f.studentId))} · ${esc(nm('courses',f.courseId))}</p><div class="note">Balance due: ${esc(fmt(M.due(f)))}</div><form data-form="payment" data-id="${id}"><div class="fields">${[F('amount','Amount received (₹)','number',true),F('date','Payment date','date',true),F('mode','Payment mode','select',true,['Cash','UPI','Bank transfer','Card','Other']),F('receipt','Receipt number','text',true),F('remarks','Payment reference / remarks')].map(x=>field(x,{amount:M.due(f),date:M.today(),receipt:'SW-'+Date.now().toString().slice(-9)})).join('')}</div><div class="form-error" role="alert"></div><div class="actions"><button class="button" type="submit">Save payment</button></div></form>`);}
function expense(id){const e=find('events',id);modal('Record event expense',`<p>${esc(e.name)}</p><form data-form="expense" data-id="${id}"><div class="fields">${[F('category','Expense category','select',true,['Artist payout','Sound','Venue','Travel','Food','Marketing','Other']),F('artistId','Artist (required for payout)','ref:artists'),F('amount','Amount paid (₹)','number',true),F('date','Payment date','date',true),F('description','Description','text',true),F('reference','Receipt / payment reference')].map(x=>field(x,{date:M.today()})).join('')}</div><div class="form-error" role="alert"></div><div class="actions"><button class="button" type="submit">Save expense</button></div></form>`);}
function reminders(){const list=M.reminders(db).filter(r=>!status||r.type===status);return `<div class="heading"><div><h1>Reminders</h1><div class="muted">Due soon, due today, and needing attention</div></div></div><div class="tabs">${['','Fee','Class','Assignment','Event'].map(x=>`<button data-action="reminder-tab" data-type="${x}" class="${status===x?'active':''}">${x||'All'}</button>`).join('')}</div><div class="note">Prepare a message, then choose WhatsApp, SMS or another app. Sending is confirmed in that app. Local daily alerts can be enabled in Settings.</div>${list.map(r=>`<article class="card"><div class="card-header"><div><h3>${esc(r.title)}</h3><p class="muted">${esc(r.subtitle)}</p></div>${badge(r.type)}</div>${button('Prepare message','remind',`data-id="${r.id}"`,'secondary small')}</article>`).join('')||empty('All caught up','No fee, class, assignment or event reminders in the next three days.')}`;}
function message(r){modal('Edit '+r.type.toLowerCase()+' reminder',`<div class="field"><label for="message">Reminder message</label><textarea id="message" rows="6" maxlength="8000" aria-describedby="reminder-help reminder-error">${esc(r.message)}</textarea><small id="reminder-help">Review and edit the message before sharing it.</small></div><div class="form-error" id="reminder-error" role="alert" aria-live="assertive"></div><div class="actions">${button(preview?'Copy edited reminder':'Choose app to send','share',`data-mobile="${esc(r.mobile||'')}"`)}</div><p class="muted" style="margin-top:14px">${preview?'The edited message is copied to your clipboard.':'This opens your phone’s share menu. You choose the recipient and confirm delivery.'}</p>`);$('#message').addEventListener('input',()=>{$('#reminder-error').textContent='';});}
const reportNames={summary:'Business summary',progress:'Student progress',trainers:'Trainer workload',fees:'Fee balances',registrations:'Student registrations',courses:'Course revenue',events:'Event profitability',artists:'Artist payouts'};
function allowedReports(){return finance()?Object.keys(reportNames):user.role==='Trainer'?['progress','trainers']:user.role==='Artist'?['artists']:['progress','fees','registrations'];}
function reports(){const types=allowedReports();if(!types.includes(reportType))reportType=types[0];const r=M.reports(db,reportType,filters.month||'');return `<div class="heading"><div><h1>Reports</h1><div class="muted">Review your institute with clarity</div></div></div><div class="toolbar"><select id="report-type" aria-label="Report type">${types.map(t=>`<option value="${t}" ${t===reportType?'selected':''}>${reportNames[t]}</option>`).join('')}</select><input type="month" id="report-month" value="${esc(filters.month||'')}" aria-label="Report month"></div>${!finance()?'<div class="note">Reports include only the records accessible to your account. Financial fields unavailable to your role appear as zero.</div>':''}<div class="card"><h2>${esc(r.title)}</h2><p class="muted">${filters.month||'All time'} · ${r.rows.length} rows</p><p class="muted">Swipe the table sideways to see every column.</p><div class="table-wrap"><table><thead><tr>${r.headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${r.rows.map(row=>`<tr>${row.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="actions">${button('Export CSV for Excel','csv')}${button('Save as PDF','pdf','','secondary')}</div></div>${reportType==='trainers'?'<div class="note">Commission is an estimate on collected student fees using current trainer assignments. It is not an automatic payment.</div>':''}${reportType==='events'?'<div class="note">Net earnings include billed organizer charges. Cash surplus includes only organizer payments received. Costs are recorded paid expenses.</div>':''}`;}
function settings(){return `<div class="heading"><div><h1>Settings</h1><div class="muted">Your records, protected and portable</div></div></div><section class="card"><h2>Institute & access</h2><p>${esc(db.institute)}<br><span class="muted">${esc(user.username)} · ${esc(user.role)}</span></p><div class="actions">${user.role==='Owner'?button('Rename institute','rename','','secondary')+button('Manage local accounts','accounts','','ghost'):''}${button('Change my PIN','change-pin','','ghost')}${button('Lock app','lock','','ghost')}${button('Exit app','exit','','danger')}</div><div class="note">Lock returns to sign in. Exit closes the Android app without deleting any records.</div></section>${user.role==='Owner'?`<section class="card"><h2>Encrypted backups</h2><p class="muted">Export a password-protected backup before changing phones. Restore it on another installation using the same backup password. PIN accounts are included.</p><div class="actions">${button('Create backup','backup')}${button('Restore backup','restore','','secondary')}</div></section>`:''}<section class="card"><h2>Phone reminders</h2><p class="muted">Enable a daily summary of due fees, upcoming classes, open assignments and upcoming events. Android may delay delivery to save battery. Each account’s alerts use its permitted records.</p><div class="actions">${button('Enable local alerts','alerts','','secondary')}${button('Turn off alerts','disable-alerts','','ghost')}</div></section>${user.role==='Owner'?`<section class="card"><h2>Getting started</h2><p class="muted">Add trainers → create work packets → enrol students → plan classes and fees.</p>${db.demoData?button('Remove legacy sample data','clear-demo','','danger small'):''}</section><section class="card"><h2>Audit history</h2>${db.audit.slice(0,30).map(x=>`<div class="audit">${esc(x.action)}<small>${esc(x.user)} · ${esc(new Date(x.at).toLocaleString('en-IN'))}</small></div>`).join('')||'<p class="muted">No changes recorded yet.</p>'}</section>`:''}<div class="note">Swara Institute 1.12 · Android 8 or later · Works offline. Online payments, multi-device sync, automatic WhatsApp / email delivery and multiple branches require a future backend integration.</div>`;}
function showExited(){user=null;db=M.empty();$('#overlay').innerHTML='';$('#app').innerHTML=`<main class="login"><div class="brand"><div class="brandmark">♪</div><div><b>Swara</b><small>Institute manager</small></div></div><div class="card"><h1>App closed</h1><p class="muted">Your records are safe. You can close this browser tab or return to sign in.</p>${button('Return to sign in','restart')}</div></main>`;}
function download(name,mime,text){if(A){A.exportFile(name,mime,text);return;}const url=URL.createObjectURL(new Blob([text],{type:mime}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function printReport(title,headers,rows){const html=`<!doctype html><html><head><meta charset="utf-8"><style>body{font:13px sans-serif;padding:25px;color:#29213e}h1{font-size:22px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:9px;border-bottom:1px solid #ddd;font-size:11px}th{background:#f1edf7}p{color:#666}thead{display:table-header-group}tr{break-inside:avoid}</style></head><body><h1>${esc(db.institute)}</h1><h2>${esc(title)}</h2><p>Generated ${esc(new Date().toLocaleString('en-IN'))}</p><table><thead><tr>${headers.map(h=>'<th>'+esc(h)+'</th>').join('')}</tr></thead><tbody>${rows.map(row=>'<tr>'+row.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')}</tbody></table></body></html>`;if(A)A.printReport(title,html);else{const w=window.open('','_blank');if(w){w.document.write(html);w.document.close();w.print();}else toast('Allow popups to print this report.');}}
function accounts(){if(preview)return toast('Secure local accounts are available in the Android APK.');const result=JSON.parse(A.listAccounts());if(result.error)return toast(result.error);modal('Local user accounts',`<p class="muted">Create accounts for people who use this phone. These accounts do not sync across devices.</p>${result.users.map(u=>`<div class="list-row"><div><b>${esc(u.username)}</b><small>${esc(u.role)} ${u.entityId?'· linked profile':''}</small></div>${u.role!=='Owner'?button('Remove','remove-account',`data-username="${esc(u.username)}"`,'danger small'):badge('Owner')}</div>`).join('')}<div class="actions">${button('Add account','add-account')}</div>`);}
function loadDemo(){try{if(db.demoData||db.students.some(r=>r.id.startsWith('demo-')))return toast('Sample data is already loaded.');if(preview){const demo=SwaraDemo.create(db.institute);for(const k of M.entities)db[k].push(...demo[k]);db.demoData=true;if(!persist('Loaded fictional sample institute'))return;}else{const result=JSON.parse(A.loadSamples());if(result.error)throw Error(result.error);db=result.state;render();}close();toast('Sample students, classes, fees and concerts are ready.');}catch(e){toast(e.message);}}
function clearDemo(){try{if(preview){const next=JSON.parse(JSON.stringify(db));for(const k of M.entities)next[k]=next[k].filter(r=>!r.id.startsWith('demo-'));for(const k of M.entities)for(const r of db[k])if(r.id.startsWith('demo-')&&M.references(next,k,r.id).length)throw Error('Some sample records are linked to other records. Remove those links first.');for(const k of M.entities)for(const r of next[k]){const errors=M.validate(next,k,r);if(errors.length)throw Error('Some sample records are linked to other records. Remove those links first.');}db=next;db.demoData=false;if(!persist('Removed fictional sample records'))return;}else{const result=JSON.parse(A.clearSamples());if(result.error)throw Error(result.error);db=result.state;render();}close();toast('Sample data removed. Your other records were kept.');}catch(e){toast('Could not remove samples: '+e.message);}}

document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(!el)return;const {action,key,id}=el.dataset;
if(action==='preview-demo'){if(!preview)return;db=JSON.parse(localStorage.getItem('swara-preview')||'null')||M.empty();user={username:'owner',role:'Owner'};page='home';filters={};if(!db.demoData)loadDemo();else render();return;}if(action==='clear-demo')return modal('Remove sample data?',`<p>This removes only the fictional records supplied with the app. Your other records are kept. Samples linked to your own records or local accounts must be unlinked first.</p>${button('Remove sample records','confirm-clear-demo','','danger')}`);if(action==='confirm-clear-demo')return clearDemo();if(action==='close')return close();if(action==='nav'){page=el.dataset.page;search='';status='';close();return render();}if(action==='lock'){if(A)A.logout();close();return showLogin();}if(action==='exit')return modal('Exit app?',`<p>Your saved records will remain on this device.</p><div class="actions">${button('Cancel','close','','ghost')}${button('Exit app','confirm-exit','','danger')}</div>`);if(action==='confirm-exit'){close();if(A)return A.exitApp();return showExited();}if(action==='restart')return showLogin();if(action==='edit'){const student=el.dataset.student?find('students',el.dataset.student):null;return edit(key,id,student?{studentId:student.id,trainerId:student.trainerId,courseId:student.courseIds[0]}:{});}if(action==='view')return view(key,id);if(action==='complete')return edit('sessions',id,{status:'Completed',actualDate:M.today(),attendance:'Present'});if(action==='paid')return paid(id);if(action==='expense')return expense(id);if(action==='people-tab'){peopleType=key;search='';status='';return render();}if(action==='reminder-tab'){status=el.dataset.type;return render();}if(action==='delete'){const refs=M.references(db,key,id);if(refs.length)return toast('Used by '+refs.join(', ')+'. Archive this record by changing its status.');return modal('Delete '+singular[key]+'?',`<p>This removes ${esc(find(key,id).name||singular[key])} from this phone. This action cannot be undone.</p>${button('Delete record','confirm-delete',`data-key="${key}" data-id="${id}"`,'danger')}`);}if(action==='confirm-delete'){db[key]=db[key].filter(r=>r.id!==id);if(persist('Deleted '+singular[key])){close();toast('Record deleted.');}return;}
if(action==='remind')return message(M.reminders(db).find(r=>r.id===id));if(action==='fee-remind'){const f=find('fees',id),s=find('students',f.studentId);return message({type:'Fee',mobile:s.guardianMobile||s.mobile,message:`Hello ${s.guardian||s.name}, the fee balance for ${nm('courses',f.courseId)} at ${db.institute} is ${fmt(M.due(f))}, due on ${f.dueDate}. Please contact us for payment.`});}if(action==='share'){const area=$('#message'),target=$('#reminder-error'),text=(area?.value||'').trim();const fail=s=>{if(target){target.textContent=s;target.tabIndex=-1;target.focus();}else toast(s);};if(!text)return fail('Enter a reminder message before sharing.');if(text.length>8000)return fail('Keep the reminder message within 8,000 characters.');if(target)target.textContent='';if(A){A.shareText(text);toast('Reminder ready. Choose an app and recipient to send it.');}else if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>toast('Edited reminder copied.')).catch(()=>fail('Could not copy the reminder. Select the text and copy it manually.'));else fail('Clipboard access is unavailable. Select the text and copy it manually.');return;}
if(action==='csv'){const r=M.reports(db,reportType,filters.month||'');download(`swara-${reportType}-${filters.month||M.today()}.csv`,'text/csv',M.csv(r));return;}if(action==='pdf'){const r=M.reports(db,reportType,filters.month||'');return printReport(r.title,r.headers,r.rows);}if(action==='receipt'){const f=find('fees',id),p=f.payments.find(p=>p.id===el.dataset.payment);return printReport('Payment receipt '+p.receipt,['Field','Details'],[['Student',nm('students',f.studentId)],['Course',nm('courses',f.courseId)],['Receipt',p.receipt],['Payment date',p.date],['Mode',p.mode],['Amount received',fmt(p.amount)],['Fee balance',fmt(M.due(f))],['Reference / remarks',p.remarks||'']]);}if(action==='registration-receipt'){const r=find('registrations',id);return printReport('Registration receipt '+r.receipt,['Field','Details'],[['Student',nm('students',r.studentId)],['Registration date',r.date],['Receipt',r.receipt],['Payment mode',r.mode],['Registration amount received',fmt(r.amount)],['Reference / remarks',r.remarks||'']]);}
if(action==='rename')return modal('Rename institute',`<form data-form="rename">${field(F('institute','Institute name','text',true),{institute:db.institute})}<div class="actions"><button class="button">Save</button></div></form>`);if(action==='accounts')return accounts();if(action==='add-account')return modal('Add local account',`<form data-form="account"><div class="fields">${[F('username','Username','text',true),F('pin','PIN (6–12 digits)','password',true),F('role','Role','select',true,['Admin','Trainer','Artist','Student / Parent','Finance']),F('entityId','Linked profile ID (auto-selected below)')].filter(f=>f.name!=='entityId').map(f=>field(f,{})).join('')}<div class="field wide"><label for="account-link">Linked profile (required for Trainer, Artist, Student / Parent)</label><select id="account-link" name="entityId"><option value="">No profile</option>${['trainers','artists','students'].map(k=>`<optgroup label="${labels[k]}">${db[k].map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</optgroup>`).join('')}</select></div></div><div class="form-error" role="alert"></div><div class="actions"><button class="button">Create account</button></div></form>`);if(action==='remove-account')return modal('Remove account?',`<p>Remove access for ${esc(el.dataset.username)}? Their institute records remain.</p>${button('Remove account','confirm-remove-account',`data-username="${esc(el.dataset.username)}"`,'danger')}`);if(action==='confirm-remove-account'){const r=JSON.parse(A.removeAccount(el.dataset.username));return r.error?toast(r.error):accounts();}
if(action==='change-pin')return modal('Change my PIN',`<form data-form="pin"><div class="fields">${[F('oldPin','Current PIN','password',true),F('newPin','New PIN (6–12 digits)','password',true),F('confirmPin','Confirm new PIN','password',true)].map(x=>field(x,{})).join('')}</div><div class="form-error" role="alert"></div><div class="actions"><button class="button">Update PIN</button></div></form>`);if(action==='backup'||action==='restore')return modal(action==='backup'?'Create encrypted backup':'Restore encrypted backup',`<p class="muted">${action==='backup'?'Choose a strong backup password of at least 10 characters. You will need it to restore.':'Choose a backup file and enter its password. Restoring replaces all records and local accounts on this phone. Create a current backup first.'}</p><form data-form="${action}">${field(F('password','Backup password (10+ characters)','password',true),{})}<div class="form-error" role="alert"></div><div class="actions"><button class="button">${action==='backup'?'Choose location & export':'Choose file & restore'}</button></div></form>`);if(action==='disable-alerts'){if(A)A.disableAlerts();else toast('Phone alerts are available in the APK.');return;}if(action==='alerts'){if(A)A.enableAlerts();else toast('Phone alerts are available in the APK.');return;}if(action==='demo')return modal('Load sample records?',`<p>This adds six fictional students, three trainers, three artists, four work packets, class history, fee receipts and two concerts. Your existing records are kept.</p>${button('Load sample data','confirm-demo')}`);if(action==='confirm-demo')return loadDemo();
});
document.addEventListener('change',ev=>{const el=ev.target;if(el.id==='filter-month')filters.month=el.value;else if(el.id==='filter-course')filters.course=el.value;else if(el.id==='filter-trainer')filters.trainer=el.value;else if(el.id==='filter-student-status')filters.status=el.value;else if(el.id==='status')status=el.value;else if(el.id==='directory-type'){directoryType=el.value;if(!directoryStatuses().includes(directoryStatus))directoryStatus='';}else if(el.id==='directory-status')directoryStatus=el.value;else if(el.id==='report-type')reportType=el.value;else if(el.id==='report-month')filters.month=el.value;else return;render();});
let searchTimer;document.addEventListener('input',ev=>{const id=ev.target.id;if(!['search','directory-search'].includes(id))return;if(id==='search')search=ev.target.value;else directoryQuery=ev.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const selector=id==='search'?'#search':'#directory-search',pos=$(selector)?.selectionStart;render();$(selector)?.focus();$(selector)?.setSelectionRange(pos,pos);},220);});
document.addEventListener('submit',ev=>{const form=ev.target.closest('[data-form]');if(!form)return;ev.preventDefault();const kind=form.dataset.form,data=Object.fromEntries(new FormData(form));const error=s=>{const target=form.querySelector('.form-error')||$('#login-error');if(target){target.textContent=s;target.tabIndex=-1;target.focus();target.scrollIntoView({block:'nearest'});}};try{
if(kind==='login'){if(form.dataset.setup==='true'&&data.pin!==data.confirmPin)return error('PINs do not match.');let result;if(preview){db=M.upgrade(JSON.parse(localStorage.getItem('swara-preview')||'null')||M.empty());if(form.dataset.setup==='true'){db=M.empty();db.institute=data.institute;localStorage.setItem('swara-preview',JSON.stringify(db));}result={state:db,username:'owner',role:'Owner'};}else result=JSON.parse(form.dataset.setup==='true'?A.setup(data.institute,data.pin):A.login(data.username,data.pin));if(result.error)return error(result.error);db=M.upgrade(result.state);user={username:result.username,role:result.role,entityId:result.entityId};page='home';filters={};return render();}
if(kind==='record'){const k=form.dataset.key,id=form.dataset.id;const old=id?find(k,id):{};const record={...old,id:id||M.id()};const fields=user.role==='Artist'?schemas[k].filter(f=>['availability','stagePreference','payoutExpectation','socialLinks'].includes(f.name)):schemas[k];for(const f of fields){if(f.type.startsWith('multi:'))record[f.name]=[...form.elements[f.name].selectedOptions].map(o=>o.value);else if(f.type==='number')record[f.name]=data[f.name]===''?undefined:Number(data[f.name]);else if(f.name==='assignmentDone')record.assignmentDone=data[f.name]==='Yes';else record[f.name]=(data[f.name]||'').trim();}if(k==='students')delete record.importPending;if(['courses','events'].includes(k)&&record.duration===undefined)delete record.durationUnit;if(k==='fees')record.payments=old.payments||[];if(k==='registrations')record.status='Paid';if(k==='events')record.expenses=old.expenses||[];const errors=M.validate(db,k,record);if(errors.length)return error(errors.join('\n'));if(id)db[k]=db[k].map(r=>r.id===id?record:r);else db[k].push(record);if(persist(`${id?'Updated':'Created'} ${singular[k]}: ${record.name||nm('students',record.studentId)}`)){close();const messages={students:id?'Student updated successfully.':'Student enrolled successfully.',trainers:id?'Trainer updated successfully.':'Trainer added successfully.',artists:id?'Artist updated successfully.':'Artist added successfully.',courses:id?'Work packet updated successfully.':'Work packet added successfully.',registrations:'Student registered and payment recorded successfully.',events:id?'Concert updated successfully.':'Concert added successfully.'};toast(messages[k]||'Saved successfully.');}return;}
if(kind==='payment'){const f=find('fees',form.dataset.id),amount=Number(data.amount);if(!Number.isFinite(amount)||amount<=0||amount>M.due(f)+.001)return error('Enter an amount above zero and within the balance due.');if(db.fees.some(f=>(f.payments||[]).some(p=>p.receipt.toLowerCase()===data.receipt.trim().toLowerCase())))return error('Receipt number is already in use.');f.payments.push({id:M.id(),...data,receipt:data.receipt.trim(),amount});if(persist(`Recorded fee collection ${fmt(amount)} · receipt ${data.receipt}`)){close();toast('Payment and receipt saved.');}return;}
if(kind==='expense'){const e=find('events',form.dataset.id),amount=Number(data.amount);if(!Number.isFinite(amount)||amount<=0)return error('Enter an amount above zero.');if(data.category==='Artist payout'&&!(e.artistIds||[]).includes(data.artistId))return error('Select an artist participating in this event.');(e.expenses||=[]).push({id:M.id(),...data,artistId:data.category==='Artist payout'?data.artistId:'',amount});if(persist(`Recorded event ${data.category.toLowerCase()} ${fmt(amount)} · ${e.name}`)){close();toast('Expense saved.');}return;}
if(kind==='rename'){db.institute=data.institute.trim();if(persist('Renamed institute'))close();return;}if(kind==='account'){const r=JSON.parse(A.addAccount(data.username,data.pin,data.role,data.entityId));if(r.error)return error(r.error);return accounts();}if(kind==='pin'){if(data.newPin!==data.confirmPin)return error('New PINs do not match.');if(preview)return error('Secure PINs are available in the Android APK.');const r=JSON.parse(A.changePin(data.oldPin,data.newPin));if(r.error)return error(r.error);close();return toast('PIN updated.');}if(kind==='backup'||kind==='restore'){if(data.password.length<10)return error('Use a backup password of at least 10 characters.');if(preview)return error('Encrypted backups are available in the Android APK.');if(kind==='backup')A.backup(data.password);else A.restore(data.password);close();return;}
}catch(e){error(e.message||'The operation could not be completed.');}});
window.nativeLocked=()=>{close();showLogin();};window.nativeNotice=s=>toast(s);window.nativeRestored=()=>{close();showLogin();toast('Backup restored. Sign in with a restored account PIN.');};window.handleBack=()=>{if($('#overlay').innerHTML){close();return true;}if(page!=='home'){page='home';search='';status='';render();return true;}return false;};showLogin();
